  function stageKind(i) { var k = (EE.data.STAGES[i] || {}).key; return k === 'estimate' ? 'draft' : (k === 'done' || k === 'paid') ? 'done' : 'fixed'; }
  function stageBadge(i) { return stBadge(stageKind(i), (EE.data.STAGES[i] || {}).label || ''); }

